<?php
declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';$db=db();$token=preg_replace('/[^a-f0-9]/','',strtolower((string)($_GET['token']??'')));$s=$db->prepare('SELECT p.*,l.name client_name,l.company,l.email,l.phone FROM proposals p JOIN leads l ON l.id=p.lead_id WHERE p.public_token=? LIMIT 1');$s->execute([$token]);$p=$s->fetch();if(!$p){http_response_code(404);exit('Proposal not found.');}$s=$db->prepare('SELECT * FROM proposal_items WHERE proposal_id=? ORDER BY sort_order,id');$s->execute([$p['id']]);$items=$s->fetchAll();$esc=static fn($v):string=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');?><!doctype html><html><head><meta charset="utf-8"><title><?=$esc($p['proposal_number'])?></title><style>@page{size:A4;margin:18mm}body{font-family:Arial,sans-serif;color:#202124;font-size:12px}.top{display:flex;justify-content:space-between;border-bottom:2px solid #222;padding-bottom:15px}.muted{color:#666}.title{margin:28px 0 8px;font-size:25px}.meta{margin:0 0 22px}.table{width:100%;border-collapse:collapse;margin-top:20px}.table th,.table td{padding:9px;border-bottom:1px solid #ddd}.table th{text-align:left;background:#f3f4f6}.num{text-align:right}.total{font-size:16px;font-weight:bold}.section{margin-top:24px}.actions{margin:20px 0}.btn{display:inline-block;padding:9px 14px;background:#222;color:#fff;text-decoration:none;border-radius:4px}@media print{.actions{display:none}} </style></head><body><div class="top"><div><h1>Distinguished Web Services</h1><div class="muted">Proposal &amp; Quotation</div></div><div class="num"><strong><?=$esc($p['proposal_number'])?></strong><br>Valid until <?=$esc($p['valid_until']?:'—')?></div></div><h2 class="title"><?=$esc($p['title'])?></h2><p class="meta">Prepared for <strong><?=$esc($p['client_name'])?></strong><?php if($p['company']):?> — <?=$esc($p['company'])?><?php endif;?><br><?=$esc($p['email'])?></p><table class="table"><thead><tr><th>Description</th><th class="num">Qty</th><th class="num">Unit</th><th class="num">Amount</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=$esc($i['description'])?></td><td class="num"><?=$esc($i['quantity'])?></td><td class="num"><?=$esc($p['currency'])?> <?=number_format((float)$i['unit_price'],2)?></td><td class="num"><?=$esc($p['currency'])?> <?=number_format((float)$i['amount'],2)?></td></tr><?php endforeach;?></tbody><tfoot><tr><td colspan="3" class="num">Subtotal</td><td class="num"><?=$esc($p['currency'])?> <?=number_format((float)$p['subtotal'],2)?></td></tr><tr><td colspan="3" class="num">Discount</td><td class="num">- <?=$esc($p['currency'])?> <?=number_format((float)$p['discount'],2)?></td></tr><tr><td colspan="3" class="num">Tax</td><td class="num"><?=$esc($p['currency'])?> <?=number_format((float)$p['tax'],2)?></td></tr><tr><td colspan="3" class="num total">Total</td><td class="num total"><?=$esc($p['currency'])?> <?=number_format((float)$p['total'],2)?></td></tr></tfoot></table><?php if($p['notes']):?><div class="section"><strong>Notes</strong><p><?=nl2br($esc($p['notes']))?></p></div><?php endif;?><?php if($p['terms']):?><div class="section"><strong>Terms &amp; Conditions</strong><p><?=nl2br($esc($p['terms']))?></p></div><?php endif;?><div class="actions"><a class="btn" href="#" onclick="window.print();return false;">Print / Save as PDF</a></div></body></html>